def list_products() -> list[dict]:
    return [dict(item, live_connection_verified=False, remote_operations_enabled=False) for item in PRODUCTS]
def get_product(product_id: str) -> dict | None:
    key=str(product_id).strip().lower()
    return next((item for item in list_products() if item["product_id"]==key or item["core_module"]==key),None)
def product_summary() -> dict:
    items=list_products()
    return {"product_count":len(items),"product_ids":[x["product_id"] for x in items]}
